using AltF4.Cinema.Core;
using Microsoft.EntityFrameworkCore;

namespace AltF4.Cinema.WinForms;

public sealed class InventoryForm : BaseForm
{
    readonly DataGridView grid=Grid();readonly ComboBox product=new(){Width=260,DropDownStyle=ComboBoxStyle.DropDownList,DisplayMember="Name",ValueMember="Id"};readonly ComboBox supplier=new(){Width=220,DropDownStyle=ComboBoxStyle.DropDownList,DisplayMember="Name",ValueMember="Id"};readonly NumericUpDown count=new(){Minimum=1,Maximum=100000,Value=10,Width=90};readonly NumericUpDown cost=new(){Maximum=100000000,ThousandsSeparator=true,Width=130};
    public InventoryForm():base("Nhập kho",1250,730){var top=Bar();top.Height=110;top.WrapContents=true;top.Controls.Add(Label("Sản phẩm"));top.Controls.Add(product);top.Controls.Add(Label("Nhà cung cấp"));top.Controls.Add(supplier);top.Controls.Add(Label("SL"));top.Controls.Add(count);top.Controls.Add(Label("Giá nhập"));top.Controls.Add(cost);top.Controls.Add(Button("Ghi phiếu nhập",()=>Run(()=>{App.Business.Receive(App.Actor,(int)(product.SelectedValue??0),(int)(supplier.SelectedValue??0),(int)count.Value,(long)cost.Value);Reload();} ),190));Controls.Add(grid);Controls.Add(top);Shown+=(_,_)=>Run(Reload);}
    void Reload(){using var db=App.Db();SecurityService.Require(db,App.Actor,Access.Inventory);product.DataSource=db.Products.Select(p=>new Choice(p.Id,p.Name+" | tồn "+p.Stock)).ToList();supplier.DataSource=db.Suppliers.Select(s=>new Choice(s.Id,s.Name)).ToList();grid.DataSource=db.InventoryReceipts.Include(x=>x.Product).Include(x=>x.Supplier).OrderByDescending(x=>x.Id).Select(x=>new{x.Id,Ngày=x.CreatedAt,Sản_phẩm=x.Product.Name,Nhà_cung_cấp=x.Supplier.Name,Số_lượng=x.Quantity,Đơn_giá=x.UnitCost,Thành_tiền=x.Quantity*x.UnitCost}).ToList();}
}
public sealed class SalesForm : BaseForm
{
    readonly DataGridView grid=Grid();readonly TextBox search=new(){Width=260,PlaceholderText="Mã hóa đơn"};readonly DateTimePicker from=new(){Width=145,Value=DateTime.Today.AddDays(-30),Format=DateTimePickerFormat.Short};readonly DateTimePicker to=new(){Width=145,Value=DateTime.Today,Format=DateTimePickerFormat.Short};
    public SalesForm():base("Tra cứu hóa đơn",1250,730){var top=Bar();top.Controls.Add(search);top.Controls.Add(from);top.Controls.Add(to);top.Controls.Add(Button("Tìm",()=>Run(Reload),90));top.Controls.Add(Button("Xem / In RDLC",()=>Run(()=>{if(grid.CurrentRow==null)throw new InvalidOperationException("Chọn hóa đơn.");ShowDialog(new InvoiceForm(Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value)),this);}),180));Controls.Add(grid);Controls.Add(top);Shown+=(_,_)=>Run(Reload);}
    void Reload(){using var db=App.Db();var u=SecurityService.Require(db,App.Actor,Access.Sell);var start=from.Value.Date;var end=to.Value.Date.AddDays(1);if(start>=end)throw new InvalidOperationException("Khoảng ngày không hợp lệ.");var canAll=(u.Role.Permissions&Access.Reports)!=0||(u.Role.Permissions&Access.Refund)!=0;grid.DataSource=db.Sales.Where(s=>s.CreatedAt>=start&&s.CreatedAt<end&&s.Code.Contains(search.Text.Trim())&&(canAll||s.UserId==u.Id)).OrderByDescending(s=>s.Id).Select(s=>new{s.Id,Mã_hóa_đơn=s.Code,Ngày=s.CreatedAt,Tạm_tính=s.Subtotal,Giảm=s.Discount,Tổng=s.Total,Trạng_thái=s.Status,Ngày_hoàn=s.RefundedAt}).ToList();}
}
public sealed class RefundForm : BaseForm
{
    public RefundForm():base("Hoàn toàn bộ hóa đơn",900,600){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new(50)};var code=new TextBox{Width=580};var reason=new TextBox{Width=580,Multiline=true,Height=90};
        panel.Controls.Add(Label("Hoàn toàn bộ vé và bắp/nước • chỉ quản lý được thực hiện"));panel.Controls.Add(Label("Mã hóa đơn"));panel.Controls.Add(code);panel.Controls.Add(Label("Lý do hoàn (5–300 ký tự)"));panel.Controls.Add(reason);panel.Controls.Add(Button("Kiểm tra và hoàn",()=>Run(()=>{using var db=App.Db();SecurityService.Require(db,App.Actor,Access.Refund);var sale=db.Sales.SingleOrDefault(s=>s.Code==code.Text.Trim())??throw new InvalidOperationException("Không tìm thấy hóa đơn.");if(MessageBox.Show(this,$"Hoàn {sale.Total:N0}đ cho {sale.Code}?","Xác nhận hoàn",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;App.Business.Refund(App.Actor,sale.Id,reason.Text);MessageBox.Show(this,"Đã hoàn; ghế, tồn kho và điểm khách hàng đã cập nhật.");}),220));panel.Controls.Add(Label("Không hoàn vé của suất đã bắt đầu.\nHóa đơn chỉ có bắp/nước: tối đa 30 phút kể từ khi mua.\nGiao dịch được lưu trong nhật ký; không xóa hóa đơn đã hoàn."));Controls.Add(panel);}
}
public sealed class AuditForm : BaseForm
{
    public AuditForm():base("Nhật ký hệ thống"){var grid=Grid();var bar=Bar();void LoadRows(){using var db=App.Db();SecurityService.Require(db,App.Actor,Access.Audit);grid.DataSource=(from log in db.AuditEntries join u in db.Users on log.UserId equals u.Id into users from u in users.DefaultIfEmpty() orderby log.Id descending select new{log.Id,Thời_điểm=log.At,Người_dùng=u==null?"Hệ thống":u.Username,Hành_động=log.Action,Nội_dung=log.Detail}).Take(1000).ToList();}bar.Controls.Add(Button("Tải lại",()=>Run(LoadRows)));bar.Controls.Add(Label("Hiển thị 1.000 sự kiện gần nhất; nhật ký chỉ đọc."));Controls.Add(grid);Controls.Add(bar);Shown+=(_,_)=>Run(LoadRows);}
}
public sealed class SettingsForm : BaseForm
{
    public SettingsForm():base("Cấu hình cơ sở dữ liệu",950,600){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new(50),FlowDirection=FlowDirection.TopDown,WrapContents=false};var path=new TextBox{Width=760,Text=App.Settings.DatabasePath};panel.Controls.Add(Label("Đường dẫn tệp SQLite (dữ liệu nằm ngoài thư mục cài đặt)"));panel.Controls.Add(path);panel.Controls.Add(Button("Chọn tệp…",()=>{using var dialog=new SaveFileDialog{Filter="SQLite|*.db",FileName="cinema.db",OverwritePrompt=false};if(dialog.ShowDialog(this)==DialogResult.OK)path.Text=dialog.FileName;}));panel.Controls.Add(Button("Lưu và thoát",()=>Run(()=>{using var db=App.Db();SecurityService.Require(db,App.Actor,Access.Configure);var full=Path.GetFullPath(path.Text.Trim());if(Path.GetExtension(full).ToLowerInvariant()!=".db"||!Directory.Exists(Path.GetDirectoryName(full)))throw new InvalidOperationException("Chọn thư mục tồn tại và tệp .db.");if(MessageBox.Show(this,"Ứng dụng sẽ thoát để đổi cơ sở dữ liệu. Dữ liệu cũ vẫn ở tệp cũ. Tiếp tục?","Cấu hình",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;App.Settings.DatabasePath=full;App.Save();Application.Exit();}),230));panel.Controls.Add(Label("Tệp mới sẽ được khởi tạo dữ liệu mẫu khi mở lại.\nKhông chia sẻ tệp SQLite qua mạng cho nhiều máy cùng ghi.\nĐóng ứng dụng trước khi sao lưu/khôi phục tệp dữ liệu."));Controls.Add(panel);}
}
public sealed class HelpForm : BaseForm
{
    public HelpForm():base("Hướng dẫn sử dụng",1000,700){Controls.Add(new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White,BorderStyle=BorderStyle.None,Text="ALTF4 CINEMA — QUẢN LÝ RẠP CHIẾU PHIM\r\n\r\n1. Quản trị: tạo nhóm quyền và tài khoản; mật khẩu mới phải đổi ở lần đăng nhập đầu.\r\n2. Quản lý danh mục: thể loại → phim; phòng → ghế; sau đó tạo suất chiếu. Hệ thống chừa 15 phút dọn phòng.\r\n3. Nhập kho: chọn sản phẩm, nhà cung cấp, số lượng, đơn giá. Không sửa tồn kho bằng tay.\r\n4. Bán vé: chọn suất, ghế xanh, khách hàng và bắp/nước. Nhập tiền nhận rồi thanh toán. Kiểm tra độ tuổi theo nhãn phim trước khi bán.\r\n5. VIP giảm 10%. Mã ALTF4 mẫu giảm 15%; chọn mức giảm cao hơn, không cộng dồn. Điểm tích lũy: mỗi 10.000đ thực thu = 1 điểm.\r\n6. In: mở hóa đơn, dùng thanh công cụ RDLC để in hoặc xuất PDF. Báo cáo lọc hai ngày bao gồm cả ngày cuối.\r\n7. Hoàn: quản lý nhập mã hóa đơn và lý do. Hoàn toàn bộ trước giờ chiếu; bắp/nước bán riêng trong 30 phút.\r\n8. Dữ liệu thật và demo tách biệt. Chạy --demo chỉ để trình diễn.\r\n9. Sao lưu: đóng tất cả phiên ứng dụng, sao chép toàn bộ thư mục dữ liệu trong LocalAppData\\AltF4Cinema.\r\n\r\nNhóm AltF4\r\nDương Đình Khôi — 51.01.104.049\r\nĐào Trọng Quyền — 51.01.104.085\r\nCổ Gia Phúc — 51.01.104.126"});}
}
